// @module vendor-frontend | Vendora v1.0 | SPIT Mini Project AY 2026-27
import { Plus, Search } from 'lucide-react';
import { useCallback, useEffect, useState } from 'react';
import AddProductPanel from '../../components/vendor/AddProductPanel';
import ProductsTable from '../../components/vendor/ProductsTable';
import Loading from '../../components/common/Loading';
import { getErrorMessage, vendorAPI } from '../../services/api';
export default function Products() {
 const[products,setProducts]=useState([]);const[loading,setLoading]=useState(true);const[error,setError]=useState('');const[search,setSearch]=useState('');const[open,setOpen]=useState(false);const[editing,setEditing]=useState(null);const[confirm,setConfirm]=useState(null);
 const load=useCallback(async()=>{setLoading(true);try{const{data}=await vendorAPI.getProducts({search,limit:100});setProducts(data.data);setError('');}catch(e){setError(getErrorMessage(e));}finally{setLoading(false);}},[search]);
 useEffect(()=>{const id=setTimeout(load,250);return()=>clearTimeout(id);},[load]);
 const archive=async()=>{if(!confirm)return;try{await vendorAPI.deleteProduct(confirm.product_id);setConfirm(null);await load();}catch(e){setError(getErrorMessage(e));}};
 return <div><div className="flex flex-wrap items-end justify-between gap-4"><div><h1 className="page-title">My Products</h1><p className="mt-1 text-sm text-slate-500">Create, edit, and archive your catalog items.</p></div><button onClick={()=>{setEditing(null);setOpen(true);}} className="flex items-center gap-2 rounded-xl bg-violet-600 px-4 py-2.5 text-sm font-bold text-white hover:bg-violet-700"><Plus className="h-4 w-4"/>Add Product</button></div><div className="mt-6 flex max-w-md items-center rounded-xl border border-slate-200 bg-white px-3"><Search className="h-4 w-4 text-slate-400"/><input value={search} onChange={(e)=>setSearch(e.target.value)} className="w-full border-0 bg-transparent text-sm focus:ring-0" placeholder="Search your products"/></div>{error&&<p className="mt-4 rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</p>}<div className="mt-5">{loading?<Loading/>:<ProductsTable products={products} onEdit={(p)=>{setEditing(p);setOpen(true);}} onDelete={setConfirm}/>}</div>{confirm&&<div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/40 p-4 backdrop-blur-sm"><div className="w-full max-w-sm rounded-2xl bg-white p-6 shadow-2xl"><h3 className="text-lg font-black">Archive product?</h3><p className="mt-2 text-sm text-slate-500">{confirm.name} will be hidden from customers. Existing order history stays intact.</p><div className="mt-5 flex justify-end gap-2"><button onClick={()=>setConfirm(null)} className="rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold">Cancel</button><button onClick={archive} className="rounded-xl bg-red-600 px-4 py-2 text-sm font-bold text-white">Archive</button></div></div></div>}<AddProductPanel open={open} product={editing} onClose={()=>setOpen(false)} onSaved={load}/></div>;
}
